@js:(function () {
  var page = String(java.ajax(String(baseUrl)));
  function grab(re) { var m = re.exec(page); return m ? m[1] : ''; }
  var mid = grab(/MANGABZ_MID\s*=\s*([0-9]+)/);
  var cid = grab(/MANGABZ_CID\s*=\s*([0-9]+)/);
  var sign = grab(/MANGABZ_VIEWSIGN\s*=\s*([0-9a-fA-F]+)/);
  var cnt = parseInt(grab(/MANGABZ_IMAGE_COUNT\s*=\s*([0-9]+)/), 10);
  if (!cid || !cnt) { return ''; }
  var path = String(baseUrl).replace(/^https?:\/\/[^\/]+/, '').replace(/\/$/, '');
  var out = [];
  for (var p = 1; p <= cnt; p++) {
    var api = 'https://www.mangabz.com' + path + '/chapterimage.ashx?cid=' + cid +
      '&page=' + p + '&key=&_cid=' + cid + '&_mid=' + mid + '&_sign=' + sign + '&_dt=';
    var payload = String(java.ajax(api));
    var code = __unpack(payload);
    if (!code) { continue; }
    var imgs = null;
    try { imgs = eval(code); } catch (e) { imgs = null; }
    if (!imgs || !imgs.length) { continue; }
    for (var i = 0; i < imgs.length; i++) {
      out.push('<img src="' + imgs[i] + '">');
    }
  }
  return out.join('');
})()
